const dict: Record<Lang, Dict> = { en, bn, hi, ta, te, ur, ar };

export const LANG_NAMES: { code: Lang; native: string; english: string; flag: string }[] = [
  { code: "bn", native: "বাংলা",    english: "Bangla",  flag: "🇧🇩" },
  { code: "en", native: "English",  english: "English", flag: "🇬🇧" },
  { code: "hi", native: "हिन्दी",     english: "Hindi",   flag: "🇮🇳" },
  { code: "ta", native: "தமிழ்",    english: "Tamil",   flag: "🇮🇳" },
  { code: "te", native: "తెలుగు",   english: "Telugu",  flag: "🇮🇳" },
  { code: "ur", native: "اردو",     english: "Urdu",    flag: "🇵🇰" },
  { code: "ar", native: "العربية",  english: "Arabic",  flag: "🇸🇦" },
];

type LegacyKey = keyof typeof en;
export type TKey = keyof typeof T | LegacyKey;

const I18nCtx = createContext<{
  lang: Lang;
  setLang: (l: Lang) => void;
  t: (k: TKey, vars?: Record<string, string | number>) => string;
}>({
  lang: "bn",
  setLang: () => {},
  t: (k) => String(k),
});

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>("bn");
  useEffect(() => {
    const saved = (typeof window !== "undefined" && localStorage.getItem("tp_lang")) as Lang | null;
    if (saved && (["bn","en","hi","ta","te","ur","ar"] as Lang[]).includes(saved)) setLangState(saved);
  }, []);
  useEffect(() => {
    if (typeof document === "undefined") return;
    document.documentElement.lang = lang;
    document.documentElement.dir = RTL_LANGS.has(lang) ? "rtl" : "ltr";
  }, [lang]);
  const setLang = (l: Lang) => {
    setLangState(l);
    if (typeof window !== "undefined") localStorage.setItem("tp_lang", l);
  };
  const t = (k: TKey, vars?: Record<string, string | number>) => {
    const tr = T[k as keyof typeof T];
    let s: string;
    if (tr) s = tr[lang] ?? tr.en ?? String(k);
    else s = dict[lang][k as LegacyKey] ?? en[k as LegacyKey] ?? String(k);
    if (vars) {
      for (const [name, val] of Object.entries(vars)) {
        s = s.replace(new RegExp(`\\{${name}\\}`, "g"), String(val));
      }
    }
    return s;
  };
  return <I18nCtx.Provider value={{ lang, setLang, t }}>{children}</I18nCtx.Provider>;
}

export const useI18n = () => useContext(I18nCtx);

// Always return English digits across the whole app — money, counts, qty,
// stock — so users get a single consistent number style regardless of UI
// language. (Earlier this converted to ০-৯ when in Bangla.)
export function bnNum(v: number | string) {
  return String(v);
}

function getCurrency(): string {
  if (typeof window === "undefined") return "BDT";
  return localStorage.getItem("tp_currency") || "BDT";
}

export function fmtMoney(v: number, lang: Lang, currency?: string) {
  const cur = currency || getCurrency();
  const sym = CURRENCY_SYMBOLS[cur] || cur;
  const s = (Math.round(v * 100) / 100).toLocaleString("en-US", { minimumFractionDigits: 0, maximumFractionDigits: 2 });
  // Digits stay English in both languages — only the currency symbol/text
  // varies. `lang` is kept in the signature for back-compat with callers.
  void lang;
  return `${sym} ${s}`;
}

// Format a date as DD-MM-YYYY. Accepts ISO string, "YYYY-MM-DD", or Date.
export function fmtDate(input: string | number | Date | null | undefined): string {
  if (!input) return "";
  const d = typeof input === "string" && /^\d{4}-\d{2}-\d{2}$/.test(input)
    ? new Date(input + "T00:00:00")
    : new Date(input);
  if (isNaN(d.getTime())) return "";
  const dd = String(d.getDate()).padStart(2, "0");
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const yyyy = d.getFullYear();
  return `${dd}-${mm}-${yyyy}`;
}
